#nullable enable

using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

public class A5_F1_ReferencedClosedGenericStructTests
{
    private const string GenericStructLibrarySource = """
using System;
using MessagePack;

namespace ReferencedLibrary
{
    [MessagePackObject]
    public struct GenericStruct<T>
    {
        [Key(0)]
        public T Content { get; set; }
    }

    [MessagePackObject]
    public struct GenericStruct2<T1, T2>
    {
        [Key(0)]
        public T1 First { get; set; }

        [Key(1)]
        public T2 Second { get; set; }
    }
}
""";

    private const string GenericStructUsageSource = """
using System;
using MessagePack;
using ReferencedLibrary;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericStruct<int> Value { get; set; }

        [Key(1)]
        public GenericStruct2<int, string> Value2 { get; set; }
    }
}
""";

    private const string GenericRecordStructLibrarySource = """
using System;
using MessagePack;

namespace ReferencedLibrary
{
    [MessagePackObject]
    public record struct GenericRecordStruct<T>
    {
        [Key(0)]
        public T Content { get; set; }
    }
}
""";

    private const string GenericRecordStructUsageSource = """
using System;
using MessagePack;
using ReferencedLibrary;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericRecordStruct<int> Value { get; set; }
    }
}
""";

    [Fact]
    public async Task A5_F1_GenericStruct_FromReferencedProject_DoesNotThrow()
    {
        string defineSource = """
using System;
using MessagePack;

namespace ReferencedLibrary
{
    [MessagePackObject]
    public struct GenericStruct<T>
    {
        [Key(0)]
        public T Content { get; set; }
    }

    [MessagePackObject]
    public struct GenericStruct2<T1, T2>
    {
        [Key(0)]
        public T1 First { get; set; }

        [Key(1)]
        public T2 Second { get; set; }
    }

    [GeneratedMessagePackResolver]
    partial class MyResolver { }
}
""";

        await new VerifyCS.Test
        {
            TestState =
            {
                Sources = { GenericStructUsageSource },
                AdditionalProjects =
                {
                    ["DefiningProject"] = { Sources = { defineSource } },
                },
                AdditionalProjectReferences = { "DefiningProject" },
            },
        }.RunAsync();
    }

    [Fact]
    public async Task A5_F1_GenericStruct_FromReferencedAssembly_DoesNotThrow()
    {
        await RunWithReferencedAssemblyAsync(GenericStructLibrarySource, GenericStructUsageSource);
    }

    [Fact]
    public async Task A5_F1_GenericRecordStruct_FromReferencedAssembly_DoesNotThrow()
    {
        await RunWithReferencedAssemblyAsync(GenericRecordStructLibrarySource, GenericRecordStructUsageSource);
    }

    private static async Task RunWithReferencedAssemblyAsync(string librarySource, string usageSource)
    {
        var test = new VerifyCS.Test
        {
            TestState =
            {
                Sources = { usageSource },
            },
        };

        var cache = new MetadataReference?[1];
        test.SolutionTransforms.Add((solution, projectId) =>
        {
            if (cache[0] is null)
            {
                Project project = solution.GetProject(projectId)!;
                var references = project.MetadataReferences
                    .Concat(test.TestState.AdditionalReferences)
                    .ToList();

                CSharpCompilation compilation = CSharpCompilation.Create(
                    "ReferencedLibrary",
                    new[] { CSharpSyntaxTree.ParseText(librarySource, new CSharpParseOptions(LanguageVersion.CSharp10)) },
                    references,
                    new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

                using var stream = new MemoryStream();
                var result = compilation.Emit(stream);
                Assert.True(
                    result.Success,
                    "Referenced library failed to compile:\n" + string.Join("\n", result.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));
                cache[0] = MetadataReference.CreateFromImage(stream.ToArray());
            }

            return solution.AddMetadataReference(projectId, cache[0]!);
        });

        await test.RunAsync();
    }
}
